$ErrorActionPreference="Stop";$workspace=(Resolve-Path(Join-Path $PSScriptRoot "..\..\..")).Path;$runtime=Join-Path $workspace "runtime\fx\official-fixings";New-Item -ItemType Directory -Force -Path $runtime|Out-Null
$line=Get-Content -LiteralPath(Join-Path $workspace ".env")|Where-Object{$_ -match '^DATABASE_URL='}|Select-Object -First 1;if(-not $line){throw"DATABASE_URL_REQUIRED"};$u=[System.UriBuilder]::new($line.Substring("DATABASE_URL=".Length).Trim().Trim('"').Trim("'"));if($u.Port-ne 6543){throw"TRANSACTION_POOLING_6543_REQUIRED"};$parts=@($u.Query.TrimStart('?').Split('&',[System.StringSplitOptions]::RemoveEmptyEntries)|Where-Object{$_ -notmatch '^(connection_limit|pgbouncer)='});$u.Query=(@($parts)+"pgbouncer=true"+"connection_limit=1")-join'&';$env:DATABASE_URL=$u.Uri.AbsoluteUri
$node=(Get-Command node.exe -ErrorAction Stop).Source;$p=Start-Process -FilePath $node -ArgumentList @("--experimental-strip-types","--env-file=.env","scripts/data/fx/run-official-fixings.ts","--background") -WorkingDirectory $workspace -RedirectStandardOutput(Join-Path $runtime "worker.stdout.log") -RedirectStandardError(Join-Path $runtime "worker.stderr.log") -WindowStyle Hidden -PassThru;$p.Id|Set-Content -LiteralPath(Join-Path $runtime "worker.pid") -Encoding ascii;[pscustomobject]@{PID=$p.Id;Alive=-not $p.HasExited;Runtime=$runtime}
